ALTER TABLE newsletter_campaigns ADD COLUMN assigned_user_id TEXT REFERENCES users(id) ON DELETE SET NULL;
ALTER TABLE newsletter_campaigns ADD COLUMN operations_revision INTEGER NOT NULL DEFAULT 1;
ALTER TABLE newsletter_campaigns ADD COLUMN provider_checked_at INTEGER;
ALTER TABLE newsletter_campaigns ADD COLUMN provider_raw_status TEXT;
