INSERT OR IGNORE INTO avy_skill_resources(id,skill_slug,title,domain,body,status,created_at,updated_at,source_kind,source_key,source_revision) VALUES('site_domain_20261108_general','site-builder','Playbook · General / personalizat','general','Protocol de context progresiv: brief minim autorizat; selectează profilul de nișă și maximum trei referințe aprobate; citește activele originale numai la nevoie și cu permisiuni. Notează versiunile și deciziile în predare. Calitatea masterelor vizuale și a site-ului nu se reduce pentru economie de tokens. Catalogul verificabil și handoffurile Codex/Claude/Lovable sunt în Site Builder → Cunoștințe și agenți.','approved',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000,'repository','general','2026-11-08.1');
INSERT OR IGNORE INTO avy_skill_resources(id,skill_slug,title,domain,body,status,created_at,updated_at,source_kind,source_key,source_revision) VALUES('site_domain_20261108_beauty','site-builder','Playbook · Beauty / wellness','beauty','Obiectiv: Programări cu serviciul și locația potrivite. Structură orientativă: Hero editorial → tratamente și durată → experiență → locații → programări → întrebări. Funcții de evaluat, nu conexiuni active: selector locație; programare prin furnizor autorizat; comparație servicii; galerie cu acord. Ipoteză de testat: claritatea duratei, locației și disponibilității poate reduce întrebările repetitive.','approved',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000,'repository','beauty','2026-11-08.1');
INSERT OR IGNORE INTO avy_skill_resources(id,skill_slug,title,domain,body,status,created_at,updated_at,source_kind,source_key,source_revision) VALUES('site_domain_20261108_recycling','site-builder','Playbook · Reciclare / economie circulară','recycling','Obiectiv: Înțelegerea pașilor și a condițiilor reale. Structură orientativă: Hero orientat spre acțiune → pași SGR → roluri → eligibilitate → funcții disponibile → întrebări. Funcții de evaluat, nu conexiuni active: explicator interactiv; status funcționalități; conturi pe roluri; formular operațional. Retuvo arată explicit funcțiile în pregătire; o machetă de interfață nu dovedește scanare ori plată activă.','approved',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000,'repository','recycling','2026-11-08.1');
INSERT OR IGNORE INTO avy_skill_resources(id,skill_slug,title,domain,body,status,created_at,updated_at,source_kind,source_key,source_revision) VALUES('site_domain_20261108_hospitality','site-builder','Playbook · Turism / ospitalitate','hospitality','Obiectiv: Cereri de rezervare complete și încredere în locație. Structură orientativă: Hero cinematic → camere → facilități confirmate → experiențe → localizare → rezervare/contact. Funcții de evaluat, nu conexiuni active: galerie pe camere; cerere disponibilitate; calendar doar cu sursă reală; traseu. Ipoteză: informațiile despre camere, acces și condiții ajută calificarea cererilor; nu inventa grad de ocupare.','approved',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000,'repository','hospitality','2026-11-08.1');
INSERT OR IGNORE INTO avy_skill_resources(id,skill_slug,title,domain,body,status,created_at,updated_at,source_kind,source_key,source_revision) VALUES('site_domain_20261108_food','site-builder','Playbook · Gastronomie / cofetărie / cafea','food','Obiectiv: Comenzi ușor de explicat și actualizat. Structură orientativă: Hero produs → meniu/catalog → opțiuni → proces comandă → livrare/ridicare → contact. Funcții de evaluat, nu conexiuni active: filtre meniu; alergeni confirmați; coș de cerere WhatsApp; opțiuni produs. Din conversația pentru un catalog de cafea: cererea prin canale existente poate preceda checkoutul; nu o prezenta ca plată online.','approved',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000,'repository','food','2026-11-08.1');
INSERT OR IGNORE INTO avy_skill_resources(id,skill_slug,title,domain,body,status,created_at,updated_at,source_kind,source_key,source_revision) VALUES('site_domain_20261108_design','site-builder','Playbook · Design / arhitectură','design','Obiectiv: Portofoliu relevant și cereri de consultanță. Structură orientativă: Hero editorial → proiecte → specializări → proces → întrebări → consultanță. Funcții de evaluat, nu conexiuni active: filtre portofoliu; galerii înainte/după cu drepturi; brief progresiv; moodboard. Ipoteză: contextul fiecărui proiect este mai util decât o galerie fără explicații.','approved',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000,'repository','design','2026-11-08.1');
INSERT OR IGNORE INTO avy_skill_resources(id,skill_slug,title,domain,body,status,created_at,updated_at,source_kind,source_key,source_revision) VALUES('site_domain_20261108_medical','site-builder','Playbook · Cabinete medicale','medical','Obiectiv: Orientare clară către serviciu și contact. Structură orientativă: Hero sobru → servicii → echipă verificată → ghid înscriere → locație/program → întrebări. Funcții de evaluat, nu conexiuni active: ghid pas cu pas; accesibilitate; programare autorizată; hartă opțională cu acord. Conversația de planificare medicală susține ghidul de înscriere și delimitarea serviciilor; fără promisiuni privind numărul de pacienți. Formularul public nu cere date medicale.','approved',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000,'repository','medical','2026-11-08.1');
INSERT OR IGNORE INTO avy_skill_resources(id,skill_slug,title,domain,body,status,created_at,updated_at,source_kind,source_key,source_revision) VALUES('site_domain_20261108_legal','site-builder','Playbook · Servicii juridice','legal','Obiectiv: Contact calificat și credibilitate profesională. Structură orientativă: Hero sobru → arii de practică → abordare → informații practice → întrebări → contact. Funcții de evaluat, nu conexiuni active: selectare arie; formular minim; conținut revizuit; navigație bilingvă. Ipoteză de design, nu analiză juridică: navigarea pe arii și contactul discret pot clarifica traseul. Fără rezultate ori clienți inventați; proiectul cabinetului existent nu se modifică.','approved',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000,'repository','legal','2026-11-08.1');
INSERT OR IGNORE INTO avy_skill_resources(id,skill_slug,title,domain,body,status,created_at,updated_at,source_kind,source_key,source_revision) VALUES('site_domain_20261108_real-estate','site-builder','Playbook · Imobiliare','real-estate','Obiectiv: Cereri relevante pe proprietăți actualizate. Structură orientativă: Hero cu căutare → proprietăți → zone → proces → întrebări → vizionare. Funcții de evaluat, nu conexiuni active: filtre utile; hartă cu alternativă listă; favorizare locală opțională; cerere vizionare. Ipoteză: calitatea datelor și actualizarea ofertelor contează mai mult decât animații ample.','approved',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000,'repository','real-estate','2026-11-08.1');
INSERT OR IGNORE INTO avy_skill_resources(id,skill_slug,title,domain,body,status,created_at,updated_at,source_kind,source_key,source_revision) VALUES('site_domain_20261108_automotive','site-builder','Playbook · Auto / service','automotive','Obiectiv: Programări și cereri cu datele necesare. Structură orientativă: Hero tehnic → servicii → proces → echipamente confirmate → întrebări → programare. Funcții de evaluat, nu conexiuni active: selector serviciu; estimare numai cu regulă aprobată; cerere constatare; contact rapid. Ipoteză: explicarea etapelor și a modului de confirmare reduce așteptările greșite.','approved',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000,'repository','automotive','2026-11-08.1');
INSERT OR IGNORE INTO avy_skill_resources(id,skill_slug,title,domain,body,status,created_at,updated_at,source_kind,source_key,source_revision) VALUES('site_domain_20261108_construction','site-builder','Playbook · Construcții / industrie','construction','Obiectiv: Cereri de ofertă tehnică și dovezi verificabile. Structură orientativă: Hero material → servicii → proiecte → proces → capacități confirmate → cerere ofertă. Funcții de evaluat, nu conexiuni active: brief proiect; documente publice aprobate; galerie pe categorie; calcule explicabile. Ipoteză: cererea structurată și limitele clare ajută oferta; nu publica certificări sau capacități neconfirmate.','approved',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000,'repository','construction','2026-11-08.1');
INSERT OR IGNORE INTO avy_skill_resources(id,skill_slug,title,domain,body,status,created_at,updated_at,source_kind,source_key,source_revision) VALUES('site_domain_20261108_transport','site-builder','Playbook · Transport / logistică','transport','Obiectiv: Cereri de cursă cu traseu și dată. Structură orientativă: Hero orientat spre trasee → servicii → proces → condiții → întrebări → cerere cursă. Funcții de evaluat, nu conexiuni active: RO/IT sau limbile reale; traseu/dată/pasageri; WhatsApp precompletat; status cerere. Lecție reutilizabilă din transportul bilingv AVYRON: fiecare limbă și rută se verifică separat; nu inventa flotă sau disponibilitate.','approved',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000,'repository','transport','2026-11-08.1');
INSERT OR IGNORE INTO avy_skill_resources(id,skill_slug,title,domain,body,status,created_at,updated_at,source_kind,source_key,source_revision) VALUES('site_domain_20261108_retail','site-builder','Playbook · Retail / produse artizanale','retail','Obiectiv: Descoperire produs și finalizare comandă. Structură orientativă: Hero produs → colecții → diferențiatori → proces → livrare → întrebări/contact. Funcții de evaluat, nu conexiuni active: variante produs; coș compact; checkout doar cu furnizor verificat; istoric. Eurostat indică oportunități de digitalizare, nu cerere garantată. Testează traseul produs → coș → confirmare și tratează integrarea separat de mockup.','approved',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000,'repository','retail','2026-11-08.1');
INSERT OR IGNORE INTO avy_skill_resources(id,skill_slug,title,domain,body,status,created_at,updated_at,source_kind,source_key,source_revision) VALUES('site_domain_20261108_business','site-builder','Playbook · B2B / servicii profesionale','business','Obiectiv: Calificare cereri și diferențiatori credibili. Structură orientativă: Hero cu beneficiu → soluții pe segment → proces → dovezi → întrebări → consultanță. Funcții de evaluat, nu conexiuni active: brief dinamic; CRM existent; comparație pachete aprobate; resurse pe rol. Lecție din wellness corporate: identitatea publică dorită și ritmul vizual al clientului au prioritate; un hero enorm nu este obligatoriu.','approved',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000,'repository','business','2026-11-08.1');
